import {createRequire} from 'node:module';import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import assert from 'node:assert/strict';import crypto from 'node:crypto';
const root='/private/tmp/pt-fix-05-06';const require=createRequire(import.meta.url);const {createQuestionManager}=require(root+'/shell/candidates/questions-20261103/index.cjs');const {createControlledExecutor,sha256}=require(root+'/shell/candidates/isolation-20261103/index.cjs');const rows=[];const identity={runId:'run-fixture',tenantId:'tenant-fixture',userId:'owner'};const respondent={respondentUserId:'owner',respondentTenantId:identity.tenantId};
async function check(id,fn){try{await fn();rows.push({id,status:'PASS'});console.log('PASS '+id);}catch(e){rows.push({id,status:'FAIL',error:e.message});console.log('FAIL '+id);}}
async function approved(options=['YES','NO']){const q=createQuestionManager(identity);const p=q.askQuestion('q-'+crypto.randomUUID(),{type:'approval',question:'Synthetic approval',options,approvalTarget:{displayedToUser:true,operationType:'run-script',operationPayload:{script:'console.log(1)'}},timeoutMs:1000});const id=q.getPendingQuestions(identity.runId)[0].questionId;const r=q.submitAnswer(id,options[0],respondent);await p;return {q,r};}
await check('QR-DENIAL-NOT-APPROVAL',async()=>{const {r}=await approved(['NO','YES']);assert.equal(r.approvalToken,null,'first option NO issued an approvalToken');});
await check('QR-CANCEL-REVOKES-ISSUED',async()=>{const {q,r}=await approved();q.cancelPendingQuestions(identity.runId);const result=q.verifyAndConsumeApproval(r.approvalToken);assert.equal(result.ok,false,'approved but unconsumed token still usable after Run cancelled');});
await check('QR-TOKEN-IMMUTABLE',async()=>{const {q,r}=await approved();r.approvalToken.operationPayloadHash=sha256('CHANGED_OPERATION');const result=q.verifyAndConsumeApproval(r.approvalToken);assert.equal(result.ok,false,'mutating returned token also mutated authority stored record');});
await check('QR-TOKEN-SCOPE',async()=>{const {q,r}=await approved();const token={...r.approvalToken,runId:'different-run',tenantId:'different-tenant'};const result=q.verifyAndConsumeApproval(token);assert.equal(result.ok,false,'verifier ignored changed run/tenant scope');});
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'pt-05-06-r1-'));const allowed=path.join(tmp,'allowed');fs.mkdirSync(allowed);const outside=path.join(tmp,'synthetic.txt');fs.writeFileSync(outside,'SYNTHETIC_ONLY');
try{await check('IR-ARBITRARY-FORGED-ID',async()=>{const script='console.log(require("node:fs").readFileSync('+JSON.stringify(outside)+',"utf8"))';const exec=createControlledExecutor({allowedPaths:[allowed],hasIsolationBackend:true});const result=await exec.controlledExec({...identity,execType:'run-script',input:{script},approvalToken:{questionId:'unissued-'+crypto.randomUUID(),operationType:'run-script',operationPayloadHash:sha256(script)}});assert.equal(result.ok,false,'changing forged questionId bypassed authority check and bare host script read outside allowedPaths');});}finally{fs.rmSync(tmp,{recursive:true,force:true});}
const report={time_utc:new Date().toISOString(),candidate:root,scope:'Actual candidates; synthetic data and harmless local child only, no PT/network/production access',sources:Object.fromEntries(['questions','isolation'].map(x=>[x,crypto.createHash('sha256').update(fs.readFileSync(root+'/shell/candidates/'+x+'-20261103/index.cjs')).digest('hex')])),total:rows.length,passed:rows.filter(x=>x.status==='PASS').length,failed:rows.filter(x=>x.status==='FAIL').length,results:rows};fs.writeFileSync('docs/refactor/evidence/QUESTIONS-ISOLATION-R1-EDGE-20261104.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,failed:report.failed}));if(report.failed)process.exitCode=1;
